SELECT *
FROM jsonb_to_recordset($faq_json$[{"category_slug":"botox","service_slug":"botox-upper-face","display_order":1,"title":"באילו אזורים מטפלים בבוטוקס לשליש העליון?","answer":"הטיפול מתייחס לקמטי המצח, לקמט שבין הגבות ולקמטי הצחוק בזוויות העיניים. האזורים והמינון נקבעים לאחר אבחון דפוסי ההבעה שלך."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":2,"title":"למי עשוי להתאים טיפול בשליש העליון?","answer":"הטיפול עשוי להתאים למי שקמטי ההבעה שלה נשארים גם במנוחה או שקמט בין הגבות מקנה למבט מראה עייף. ההתאמה נבחנת בפגישה אישית."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":3,"title":"כמה זמן נמשך הטיפול?","answer":"הטיפול עצמו נמשך כעשר עד חמש עשרה דקות, כחלק מפגישה הכוללת אבחון של דפוסי ההבעה."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":4,"title":"מתי מתחילים לראות שינוי?","answer":"השפעה עשויה להתחיל לאחר שלושה עד חמישה ימים ולהגיע לשיאה בתוך כשבועיים. התגובה משתנה מאדם לאדם."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":5,"title":"כמה זמן ההשפעה נמשכת?","answer":"לפי תיאור הטיפול, ההשפעה נמשכת בממוצע כשלושה עד ארבעה חודשים; משכה בפועל משתנה."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":6,"title":"האם אפשר לחזור לשגרה אחרי הטיפול?","answer":"לפי תיאור הטיפול ניתן לחזור לשגרה מיד, אך מומלץ להימנע מספורט מאומץ, מחום ומשכיבה במשך ארבע שעות. הנחיות אישיות יינתנו בפגישה."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":7,"title":"אילו תופעות עשויות להופיע לאחר ההזרקה?","answer":"ייתכן אודם קל בנקודות ההזרקה, שלפי התיאור חולף בתוך שעות. תופעות והחלמה אישיות עשויות להשתנות."},{"category_slug":"botox","service_slug":"botox-upper-face","display_order":8,"title":"האם הטיפול מתאים בהריון או בהנקה?","answer":"הטיפול אינו מתאים בהריון או בהנקה לפי תיאור השירות. אם אחד המצבים רלוונטי, יש לציין זאת בייעוץ ולברר התאמה."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":1,"title":"באילו מצבים שוקלים בוטוקס לשליש התחתון?","answer":"הטיפול מתואר עבור סנטר בעל מראה מגומם, זוויות פה שנוטות מטה וקווים היורדים מהפה. נדרש אבחון של תנועת הפה וההבעה."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":2,"title":"האם הטיפול מתאים לכל אחת?","answer":"לא בהכרח. הטיפול דורש אבחון זהיר, ולעיתים אינו מתאים כטיפול עצמאי ללא השלמה בחומצה היאלורונית. ההתאמה נקבעת לאחר בדיקה."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":3,"title":"איך בודקים את תנועת הפה לפני הטיפול?","answer":"האבחון כולל בדיקת תנועת הפה בזמן דיבור ובחיוך, כדי לתכנן את הטיפול בהתאם לתפקוד ולהבעה."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":4,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כעשרים דקות. התכנון עשוי לכלול גם בחינה של צורך בטיפול משלים."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":5,"title":"מתי מופיעה ההשפעה ולכמה זמן?","answer":"לפי תיאור השירות, התוצאה מופיעה בהדרגה בתוך כשבוע ונמשכת כשלושה עד ארבעה חודשים בממוצע; התגובה משתנה."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":6,"title":"האם יכולה להיות נפיחות אחרי הטיפול?","answer":"ייתכנו נפיחות קלה או רגישות באזור למשך כמה שעות, לפי המידע המתואר. יש לברר בייעוץ מה צפוי במקרה שלך."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":7,"title":"למה חשוב להגיע למעקב?","answer":"המעקב נועד לבדוק את התגובה ואת האיזון בין צדי הפנים. לפי התיאור, מומלץ להגיע למעקב לאחר הטיפול."},{"category_slug":"botox","service_slug":"botox-lower-face","display_order":8,"title":"האם הטיפול עלול להשפיע על דיבור או אכילה?","answer":"תכנון הטיפול מתייחס לשמירה על תפקוד הדיבור והאכילה, אך לא ניתן לקבוע מראש מה תהיה התגובה האישית. יש לדון בתפקוד ובציפיות במהלך האבחון."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":1,"title":"מה כולל טיפול בוטוקס פול פייס?","answer":"זהו תכנון שעשוי לכלול את השליש העליון והתחתון, ולעיתים גם את קו הלסת והצוואר, לפי מיפוי הפנים וההתאמה האישית."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":2,"title":"למי מיועד טיפול פול פייס?","answer":"לפי תיאור השירות, הוא מיועד בעיקר למטופלות מנוסות שכבר מכירות את תגובת גופן לטוקסין ומעוניינות בתכנון כולל. ההתאמה נבדקת בייעוץ."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":3,"title":"האם כל אזורי הפנים מטופלים בכל פגישה?","answer":"לא בהכרח. התכנון כולל מיפוי והתאמת הטיפול לאזורים ולשרירים שנמצאים מתאימים; לא כל אזור חייב להיכלל."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":4,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כשלושים עד ארבעים דקות, כולל מיפוי הפנים ותכנון הטיפול."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":5,"title":"מתי התוצאה מתגבשת?","answer":"לפי תיאור השירות, התוצאה המלאה מתגבשת בתוך כשבועיים. התגובה האישית עשויה להשתנות."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":6,"title":"כמה זמן התוצאה נמשכת?","answer":"התיאור מציין משך ממוצע של כארבעה חודשים; משך ההשפעה בפועל משתנה בין מטופלות."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":7,"title":"מה מומלץ לעשות אחרי הטיפול?","answer":"לפי הנחיות התיאור, מומלץ להימנע מספורט ומחום ביממה הראשונה. הנחיות אישיות יימסרו בפגישה."},{"category_slug":"botox","service_slug":"botox-full-face","display_order":8,"title":"מתי מתקיים מעקב?","answer":"תיאור השירות כולל פגישת מעקב כשבועיים לאחר הטיפול, לבחינת התגובה והמשך התכנון."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":1,"title":"מהו חיוך גאמי?","answer":"זהו מצב שבו השפה העליונה מתרוממת וחושפת רצועת חניכיים רחבה בזמן חיוך. מקור החשיפה נבדק לפני שמחליטים על טיפול."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הטיפול עשוי להתאים למי שמוטרדת מחשיפת החניכיים בזמן חיוך או בצילום, כאשר הגורם קשור לשריר השפה העליונה."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":3,"title":"האם הטיפול מתאים אם מקור החשיפה הוא מבני?","answer":"אם המקור הוא מבני, כגון עודף רקמת חניכיים או מבנה לסת, הטיפול אינו מתואר כמתאים. אבחון המקור חשוב לפני החלטה."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":4,"title":"כמה זמן נמשכת ההשפעה?","answer":"לפי תיאור השירות, השינוי נמשך כשלושה עד ארבעה חודשים. משך ההשפעה משתנה מאדם לאדם."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":5,"title":"מתי אפשר להבחין בשינוי?","answer":"השינוי עשוי להיות מורגש בתוך שלושה עד שבעה ימים, לפי תיאור השירות."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":6,"title":"האם יכולה להיות השפעה זמנית על השפה?","answer":"ייתכן שינוי קל וזמני בהגייה או בתחושת השפה בימים הראשונים. יש לדון בתפקוד ובחששות שלך במהלך הייעוץ."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":7,"title":"מה בודקים לפני הטיפול?","answer":"בבדיקה מעריכים את גובה החיוך ומבררים אם חשיפת החניכיים קשורה לתנועת השפה או למבנה אחר."},{"category_slug":"botox","service_slug":"gummy-smile","display_order":8,"title":"האם אפשר לדעת מראש מה יהיה היקף השינוי?","answer":"היקף השינוי משתנה ותלוי בממצאי הבדיקה ובתגובה האישית."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":1,"title":"באילו מצבים שוקלים טיפול בברוקסיזם?","answer":"לפי תיאור השירות, שוקלים אותו במקרים של חריקת שיניים, כיווץ לסתות, לסת תפוסה בבוקר, כאב ראש או שחיקת סתימות. מומלץ לתאם עם רופאת השיניים המטפלת."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":2,"title":"האם הטיפול עשוי להשפיע על מראה קו הלסת?","answer":"התיאור מציין שעידון קו הלסת עשוי להתפתח בהדרגה, לצד הטיפול בשרירי הלעיסה. המידה והתוצאה משתנות בין אנשים."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":3,"title":"מתי עשויה להופיע הקלה בכאב?","answer":"לפי התיאור, הקלה בכאב מורגשת לרוב בתוך שבוע עד שבועיים. התגובה משתנה בין אנשים."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":4,"title":"מתי משתנה מתאר הלסת?","answer":"עידון קו הלסת מתפתח לפי התיאור לאורך כחודשיים עד שלושה. השינוי תלוי בתגובה האישית."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":5,"title":"כמה זמן נמשכת ההשפעה?","answer":"תיאור השירות מציין משך של כארבעה עד שישה חודשים, אך ההשפעה משתנה בין מטופלות."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":6,"title":"האם הלעיסה יכולה להרגיש אחרת לאחר הטיפול?","answer":"בימים הראשונים תיתכן תחושת עייפות קלה בזמן לעיסה, לפי התיאור. אם יש חשש הנוגע לתפקוד שלך, חשוב להעלות אותו בייעוץ."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":7,"title":"מה כולל האבחון?","answer":"במהלך הבדיקה ממששים את השריר בזמן כיווץ כדי להעריך את הפעילות באזור ולבחון התאמה."},{"category_slug":"botox","service_slug":"bruxism-jaw","display_order":8,"title":"האם הטיפול מחליף ייעוץ של רופאת שיניים?","answer":"לא. תיאור השירות ממליץ על תיאום עם רופאת השיניים המטפלת, וההתאמה הכוללת נבחנת בייעוץ רפואי אישי."},{"category_slug":"botox","service_slug":"botox-neck","display_order":1,"title":"מה מטפלים בבוטוקס לצוואר?","answer":"הטיפול מתואר עבור רצועות אנכיות של שריר הפלטיסמה ומראה המעבר בין הפנים לצוואר."},{"category_slug":"botox","service_slug":"botox-neck","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הוא עשוי להתאים למי שרואה רצועות צוואר בולטות, במיוחד בזמן דיבור, או מוטרדת מהמעבר בין קו הלסת לצוואר."},{"category_slug":"botox","service_slug":"botox-neck","display_order":3,"title":"האם הטיפול יעיל בעודף עור משמעותי?","answer":"לפי תיאור השירות, הטיפול פחות יעיל כשיש עודף עור משמעותי; ייתכן שיומלץ לשקול טיפול מיצוק. ההתאמה תלויה בבדיקה."},{"category_slug":"botox","service_slug":"botox-neck","display_order":4,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כעשרים עד שלושים דקות."},{"category_slug":"botox","service_slug":"botox-neck","display_order":5,"title":"מתי מופיעה התוצאה ולכמה זמן?","answer":"לפי התיאור, התוצאה נראית בתוך שבוע עד שבועיים ונמשכת כשלושה עד ארבעה חודשים. משך ההשפעה משתנה."},{"category_slug":"botox","service_slug":"botox-neck","display_order":6,"title":"האם צפויים סימנים באזור?","answer":"ייתכנו שטפי דם קטנים באזור הצוואר, ולפי התיאור הם חולפים בתוך מספר ימים."},{"category_slug":"botox","service_slug":"botox-neck","display_order":7,"title":"איך מזהים את אזור הטיפול?","answer":"במהלך הבדיקה מתבקשים לכווץ את שרירי הצוואר כדי לזהות את הרצועות. התכנון נקבע לאחר הערכה אישית."},{"category_slug":"botox","service_slug":"botox-neck","display_order":8,"title":"האם משלבים טיפולים נוספים?","answer":"תיאור השירות מציין שלעיתים משלבים טיפולי איכות עור. האם שילוב מתאים לך נקבע בייעוץ."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":1,"title":"מהו נפרטיטי ליפט?","answer":"זהו טיפול בטוקסין לאורך קו הלסת ובחלק העליון של הצוואר, שמטרתו חידוד עדין של קו הלסת באמצעות הרפיית שרירים המושכים מטה."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":2,"title":"האם הטיפול מוסיף נפח?","answer":"לא. לפי תיאור השירות, נפרטיטי ליפט אינו כולל מילוי בחומצה היאלורונית; מטרתו חידוד עדין."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":3,"title":"למי עשוי להתאים הטיפול?","answer":"הוא עשוי להתאים למי שמוטרדת מטשטוש מוקדם של קו הלסת ומחפשת חידוד עדין ללא הוספת נפח. התאמה נבדקת בפגישה."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":4,"title":"האם הטיפול מחליף מתיחה כירורגית?","answer":"לא. התיאור מדגיש שמדובר בחידוד ולא במתיחה כירורגית, ולכן חשוב לתאם ציפיות בייעוץ."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":5,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כשלושים דקות."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":6,"title":"מתי מורגש השיפור?","answer":"לפי התיאור, השיפור מורגש בהדרגה בתוך כשבועיים. התגובה האישית משתנה."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":7,"title":"כמה זמן ההשפעה נמשכת?","answer":"לפי תיאור השירות, ההשפעה נמשכת כשלושה עד ארבעה חודשים, ולעיתים השיפור מצטבר לאחר סדרת טיפולים."},{"category_slug":"botox","service_slug":"nefertiti-lift","display_order":8,"title":"האם נדרש זמן התאוששות?","answer":"תיאור השירות מציין שאין זמן התאוששות, אך יש לברר בייעוץ אילו הנחיות מתאימות לך."},{"category_slug":"botox","service_slug":"glowtox","display_order":1,"title":"מה ההבדל בין גלואוטוקס לבוטוקס רגיל?","answer":"גלואוטוקס מוזרק באופן שטחי ומדולל ומתואר כטיפול במרקם, בשומניות ובנקבוביות, ולא בהרפיית שרירי ההבעה."},{"category_slug":"botox","service_slug":"glowtox","display_order":2,"title":"למי עשוי להתאים גלואוטוקס?","answer":"הטיפול עשוי להתאים למי שמוטרדת מעור שמנוני, מנקבוביות מורחבות או מחוסר זוהר, ומחפשת שיפור במרקם בלי שינוי בהבעה."},{"category_slug":"botox","service_slug":"glowtox","display_order":3,"title":"באילו אזורים מטפלים?","answer":"תיאור השירות מתייחס לפנים ולצוואר. האזור המדויק נקבע לאחר בדיקה וייעוץ."},{"category_slug":"botox","service_slug":"glowtox","display_order":4,"title":"כמה זמן נמשכת הפגישה?","answer":"הפגישה נמשכת כארבעים דקות, כולל זמן ההרדמה המקומית במשחה, לפי התיאור."},{"category_slug":"botox","service_slug":"glowtox","display_order":5,"title":"מתי רואים שינוי?","answer":"הזוהר ושיפור המרקם מתפתחים לפי התיאור בתוך כשבועיים. התגובה משתנה מאדם לאדם."},{"category_slug":"botox","service_slug":"glowtox","display_order":6,"title":"כמה זמן ההשפעה נמשכת?","answer":"לפי התיאור, ההשפעה נמשכת כשלושה חודשים; משכה בפועל עשוי להשתנות."},{"category_slug":"botox","service_slug":"glowtox","display_order":7,"title":"האם ייתכנו סימנים לאחר הטיפול?","answer":"ייתכנו אודם קל ונקודות הזרקה זעירות למשך מספר שעות, לפי תיאור השירות."},{"category_slug":"botox","service_slug":"glowtox","display_order":8,"title":"האם אפשר לשלב גלואוטוקס עם טיפול אחר?","answer":"תיאור השירות מציין אפשרות לשלב עם טיפולי איכות עור, אך שילוב ותזמון מתאימים נקבעים בייעוץ אישי."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":1,"title":"מה כולל פיסול פנים מלא?","answer":"זהו תכנון רב־אזורי בחומצה היאלורונית להשבת נפחים ולעיצוב מתאר הפנים. אזורים אפשריים כוללים לחיים, רקות, קו לסת וסנטר, לפי האבחון."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הטיפול עשוי להתאים למי שמרגישה שפניה נראות עייפות או שקועות, רואה צניחה הדרגתית בלחיים או מעוניינת באיזון אסימטריה."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":3,"title":"כמה מפגשים נדרשים?","answer":"לרוב התכנון מחולק לשניים עד שלושה מפגשים, לפי תיאור השירות. מספר המפגשים נקבע בהתאם למצב ההתחלתי."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":4,"title":"מה כולל המפגש הראשון?","answer":"המפגש הראשון מוקדש לאבחון, לצילום ולתכנון מפת הטיפול. החלטה על אזורים ועל שלבי טיפול מתקבלת באופן אישי."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":5,"title":"כמה זמן נמשכת ההחלמה הראשונית?","answer":"נפיחות ורגישות שכיחות בימים הראשונים, וייתכנו שטפי דם שחולפים בתוך כשבוע. התגובה משתנה בין מטופלות."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":6,"title":"מתי התוצאה מתייצבת?","answer":"לפי תיאור השירות, התוצאה מתייצבת בתוך כשבועיים. תוצאה אישית תלויה בחומר ובאזור."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":7,"title":"כמה זמן התוצאה נמשכת?","answer":"התיאור מציין טווח של שנה עד שנתיים, בהתאם לחומר ולאזור. משך התוצאה בפועל משתנה."},{"category_slug":"hyaluronic-acid","service_slug":"full-face-sculpting","display_order":8,"title":"האם הטיפול מתאים בהריון או בהנקה?","answer":"לפי תיאור השירות, הוא אינו מתאים בהריון או בהנקה, וגם לא במצב של זיהום פעיל באזור. יש לברר כל מצב אישי בייעוץ."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":1,"title":"מה אפשר לשפר בעיצוב שפתיים?","answer":"הטיפול מתואר להשבת נפח, לאיזון בין השפתיים, לחידוד קשת הקופידון ולשיפור מתאר השפתיים וזוויות הפה, לפי הצורך."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":2,"title":"למי עשוי להתאים מילוי שפתיים?","answer":"הטיפול עשוי להתאים למי שמוטרדת משפתיים דקות או אסימטריות, מאובדן נפח או מזוויות פה שיורדות."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":3,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כארבעים דקות, לאחר הרדמה מקומית במשחה."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":4,"title":"האם צפויה נפיחות אחרי הטיפול?","answer":"נפיחות משמעותית בימים הראשונים מתוארת כחלק אפשרי מהתהליך, והשפתיים עשויות להיראות גדולות מהתוצאה שתתייצב."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":5,"title":"מתי מראה השפתיים מתייצב?","answer":"לפי תיאור השירות, המראה מתייצב בתוך שבוע עד שבועיים. התגובה האישית עשויה להשתנות."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":6,"title":"כמה זמן התוצאה נמשכת?","answer":"התיאור מציין משך של כשמונה עד שנים עשר חודשים; בפועל משך התוצאה עשוי להשתנות."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":7,"title":"האם אפשר להתאים את מידת הנפח?","answer":"תיאור השירות מציין שניתן לשלוט במידת הנפח באמצעות בחירת החומר והטכניקה. האפשרות המתאימה לך נקבעת בייעוץ."},{"category_slug":"hyaluronic-acid","service_slug":"lip-filler","display_order":8,"title":"מה לגבי הרפס לפני טיפול?","answer":"הטיפול אינו מתאים בזמן הרפס פעיל. אם יש לך נטייה להרפס, בתיאור מומלץ לברר טיפול מניעתי מראש עם הרופאה."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":1,"title":"למי עשוי להתאים מילוי שקעי עיניים?","answer":"הטיפול עשוי להתאים כאשר השקע מתחת לעין נובע מאובדן נפח. נדרשת הערכה קפדנית של האזור ושל הלחיים."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":2,"title":"האם הטיפול מתאים לשקיות מתחת לעיניים?","answer":"במקרים של שקיות שומן בולטות הטיפול עלול להחמיר את המראה, ולכן ייתכן שיוצע פתרון אחר לאחר בדיקה."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":3,"title":"מה לגבי בצקות כרוניות או עור דק?","answer":"בצקות כרוניות או עור דק במיוחד עלולים להפוך את הטיפול לפחות מתאים ואף להחמיר את המראה. ההחלטה מתקבלת לאחר אבחון."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":4,"title":"האם צריך לבדוק גם את הלחיים?","answer":"כן. תיאור השירות מציין הערכה של הלחיים לפני טיפול, ולעיתים איזון שלהן לפני מילוי שקעי העיניים."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":5,"title":"כמה מפגשים עשויים להידרש?","answer":"לרוב נדרשים שני מפגשים לפי תיאור השירות, אך התכנון תלוי בבדיקה ובתגובה."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":6,"title":"האם ייתכנו נפיחות או שטפי דם?","answer":"כן. נפיחות קלה ושטפי דם אפשריים ועלולים להימשך עד כשבוע, לפי המידע המתואר."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":7,"title":"מתי התוצאה מתייצבת ולכמה זמן?","answer":"התוצאה מתייצבת לפי התיאור בתוך כשבועיים ונמשכת כשנה עד שנה וחצי. משך התוצאה בפועל משתנה."},{"category_slug":"hyaluronic-acid","service_slug":"under-eye-filler","display_order":8,"title":"האם כל שקע מתחת לעין מתאים למילוי?","answer":"לא. ההתאמה תלויה בסיבה לשקע ובמצב העור, השומן, הבצקת והלחיים; אם הטיפול אינו מתאים, ייתכן שתופני לאפשרות אחרת."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":1,"title":"מה מטרת עיצוב קו הלסת?","answer":"הטיפול נועד להגדיר את מתאר הלסת והסנטר, לאזן סנטר נסוג ולשפר את המעבר בין הפנים לצוואר, בהתאם למבנה הפנים."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הטיפול עשוי להתאים למי שקו הלסת שלה מטושטש, מעוניינת בהבלטת הסנטר או באיזון הפרופיל."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":3,"title":"האם עודף עור או שומן מתחת לסנטר מתאים לטיפול?","answer":"במקרה של עודף משמעותי של עור או שומן מתחת לסנטר, ייתכן שיומלץ על טיפול במכשור רפואי. ההתאמה נקבעת לאחר בדיקה."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":4,"title":"מה נבדק לפני טיפול בקו הלסת?","answer":"ממפים את הפרופיל והמתאר ומעריכים את הנפחים בפנים. לפי הממצאים נשקלת השבת נפחים באזורים נוספים."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":5,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כחצי שעה."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":6,"title":"אילו תופעות עשויות להופיע?","answer":"נפיחות ורגישות בלסת למשך מספר ימים אפשריות, ולעיתים מופיע שטף דם מקומי."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":7,"title":"מתי רואים את התוצאה המלאה?","answer":"לפי תיאור השירות, התוצאה המלאה נראית בתוך כשבועיים."},{"category_slug":"hyaluronic-acid","service_slug":"jawline-contouring","display_order":8,"title":"כמה זמן התוצאה נמשכת?","answer":"התיאור מציין משך של שנה עד שנתיים, בהתאם לכמות ולסוג החומר. התוצאה בפועל עשויה להשתנות."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":1,"title":"מה מטרת מילוי הרקות?","answer":"הטיפול נועד להשיב נפח באזור הרקות, לאזן את החלק העליון של הפנים ולשפר את המעבר אל הלחי."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":2,"title":"למי עשוי להתאים מילוי רקות?","answer":"הטיפול עשוי להתאים למי שרואה שקיעה בצדי המצח, מבחינה בשינוי במראה הגבות או עברה ירידה משמעותית במשקל."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":3,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כשלושים דקות."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":4,"title":"מה חשוב לדעת על אזור הרקות?","answer":"האזור עשיר בכלי דם ודורש הערכה והזרקה מנוסה. ההתאמה והגישה נבחנות בפגישה."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":5,"title":"האם יש כאב או רגישות לאחר הטיפול?","answer":"לפי התיאור, כאב בלסת עשוי להופיע ולהשתפר לאחר מספר ימים. תיתכן גם רגישות באזור ההזרקה ונפיחות קלה."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":6,"title":"מתי מבחינים בתוצאה?","answer":"התוצאה עשויה להיראות כמעט מיד ולהשתפר בתוך כשבועיים, לפי תיאור השירות."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":7,"title":"כמה זמן התוצאה נמשכת?","answer":"התיאור מציין שנה עד שנתיים, בהתאם לכמות החומר ולשינויים פיזיולוגיים; משך ההשפעה משתנה."},{"category_slug":"hyaluronic-acid","service_slug":"temple-filler","display_order":8,"title":"האם הטיפול מתאים לכל מי שרואה שקיעה ברקות?","answer":"לא ניתן לקבוע התאמה לפי מראה בלבד. נדרשת בדיקה אישית של האזור, המבנה והציפיות."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":1,"title":"מהם קמטי ברקוד?","answer":"אלה קווים אנכיים דקים מעל השפה העליונה. הטיפול מתואר כשילוב אפשרי של חומצה היאלורונית דלילה וטיפולי חידוש עור."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הוא עשוי להתאים למי שרואה קווים אנכיים מעל השפה גם במנוחה. לפי התיאור, הקווים נפוצים גם אצל מעשנות, מעשנות לשעבר ונשים לאחר גיל המעבר."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":3,"title":"האם תמיד משתמשים גם בטוקסין?","answer":"לא. לפי התיאור, לעיתים משלבים טוקסין במינון נמוך כדי להפחית את כיווץ שריר השפה; ההחלטה תלויה באבחון."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":4,"title":"האם נדרשת הרדמה?","answer":"תיאור הטיפול מציין שימוש בהרדמה מקומית במשחה. הפרטים מותאמים לתוכנית הטיפול האישית."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":5,"title":"אילו תופעות עשויות להופיע?","answer":"נפיחות קלה ורגישות למשך מספר ימים אפשריות, וייתכנו שטפי דם קטנים."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":6,"title":"מתי מתייצבת התוצאה?","answer":"לפי תיאור השירות, התוצאה מתייצבת בתוך כשבועיים."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":7,"title":"כמה זמן התוצאה נמשכת?","answer":"התיאור מציין עד כשנה, אך משך התוצאה משתנה בין אנשים."},{"category_slug":"hyaluronic-acid","service_slug":"barcode-lines","display_order":8,"title":"מה אפשר לשקול במקרה של קמטים עמוקים?","answer":"לפי תיאור השירות, במקרים של קמטים עמוקים עשוי להיות מומלץ לשלב לייזר או מיקרונידלינג. ההתאמה נבחנת בייעוץ."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":1,"title":"האם סקין בוסטר מוסיף נפח לפנים?","answer":"לא. לפי תיאור השירות, סקין בוסטר משפר לחות, גמישות וזוהר בלי להוסיף נפח או לשנות את צורת הפנים."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הטיפול עשוי להתאים למי שהעור שלה יבש, עייף או איבד גמישות, וכן לעור עם נזקי שמש. התאמה אישית נבדקת בייעוץ."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":3,"title":"באילו אזורים אפשר לטפל?","answer":"תיאור השירות מציין פנים, צוואר, מחשוף וגב כפות הידיים. האזור המתאים נקבע לפי בדיקה."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":4,"title":"כמה מפגשים נדרשים ובאיזה מרווח?","answer":"לרוב מתוארים שניים עד שלושה מפגשים בהפרש של שלושה עד ארבעה שבועות. התוכנית תלויה במצב ההתחלתי."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":5,"title":"כמה זמן נמשך מפגש?","answer":"תיאור הטיפול מציין פגישה של כעשרים דקות, עם הזרקות זעירות לאחר אלחוש במשחה."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":6,"title":"האם צפויות בליטות או נקודות הזרקה?","answer":"בליטות קטנות ונקודות הזרקה עשויות להיראות עד כיממה, לפי תיאור השירות."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":7,"title":"מתי מתפתח השיפור?","answer":"השיפור מצטבר לאורך הסדרה ומגיע לשיאו כחודש לאחר המפגש האחרון, לפי התיאור."},{"category_slug":"skin-quality","service_slug":"skin-booster","display_order":8,"title":"כמה זמן נשמרת התוצאה?","answer":"ההערכה בתיאור היא כתשעה חודשים עד שנה. משך התוצאה משתנה בין אנשים."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":1,"title":"מהו רדיאס היברידי?","answer":"זהו רדיאס מדולל לשימוש שטחי יותר, המתואר לשיפור מרקם ומיצוק באזורים רחבים. החומר מבוסס קלציום הידרוקסיאפטיט."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":2,"title":"האם הטיפול נועד להוסיף נפח?","answer":"לפי תיאור השירות, מטרתו מיצוק ושיפור מרקם ולא הוספת נפח."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":3,"title":"באילו אזורים אפשר לשקול טיפול?","answer":"התיאור מציין לחיים, צוואר, מחשוף וזרועות. אזור הטיפול נקבע לאחר בדיקת התאמה."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":4,"title":"האם הטיפול מתאים לשפתיים?","answer":"לא. לפי תיאור השירות, הוא אינו מתאים לאזורים דינמיים מאוד כמו השפתיים."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":5,"title":"כמה מפגשים נהוג לתכנן?","answer":"לרוב מתוארים שניים עד שלושה מפגשים, בהפרש של חודש עד חודשיים, בהתאם למצב ההתחלתי."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":6,"title":"האם תיתכן נפיחות לאחר הטיפול?","answer":"נפיחות קלה ורגישות למשך כמה ימים אפשריות לפי תיאור השירות."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":7,"title":"מתי מתפתח השיפור?","answer":"ייתכן שינוי ראשוני מיד, אך השיפור מתפתח בעיקר לאורך שלושה עד שישה חודשים ככל שנבנה קולגן, לפי התיאור."},{"category_slug":"skin-quality","service_slug":"hybrid-radiesse","display_order":8,"title":"כמה זמן ההשפעה עשויה להימשך?","answer":"התיאור מציין עד כשנה וחצי. משך ההשפעה בפועל עשוי להשתנות."},{"category_slug":"skin-quality","service_slug":"prp","display_order":1,"title":"מהו טיפול PRP?","answer":"בטיפול משתמשים בפלזמה עשירה בטסיות מדגימת דם עצמית, לאחר הפרדה בצנטריפוגה, לשימוש בעור."},{"category_slug":"skin-quality","service_slug":"prp","display_order":2,"title":"למי עשוי להתאים PRP?","answer":"לפי תיאור השירות, ניתן לשקול אותו למי שמוטרדת מעור עייף, מצלקות אקנה או מהידלדלות שיער. ההתאמה תלויה בבדיקה."},{"category_slug":"skin-quality","service_slug":"prp","display_order":3,"title":"מתי הטיפול אינו מתאים לפי המידע באתר?","answer":"הטיפול אינו מתאים במצבי הפרעות קרישה, מחלות דם או טיפול נוגד קרישה, לפי תיאור השירות. יש למסור לרופאה מידע רפואי מלא."},{"category_slug":"skin-quality","service_slug":"prp","display_order":4,"title":"איך מתבצע הטיפול?","answer":"נלקחת דגימת דם ומופרדת בצנטריפוגה; לאחר מכן הפלזמה מוזרקת לעור או מועברת באמצעות מיקרונידלינג, לפי התוכנית."},{"category_slug":"skin-quality","service_slug":"prp","display_order":5,"title":"כמה מפגשים נהוג לתכנן?","answer":"לרוב מומלצת סדרה של שלושה מפגשים בהפרש של כחודש, לפי תיאור השירות."},{"category_slug":"skin-quality","service_slug":"prp","display_order":6,"title":"אילו תופעות עשויות להופיע?","answer":"אודם ונפיחות קלה למשך יום עד יומיים אפשריים, לפי התיאור."},{"category_slug":"skin-quality","service_slug":"prp","display_order":7,"title":"מתי אפשר להבחין בשינוי?","answer":"השיפור מתואר כהדרגתי ומורגש בעיקר לאחר המפגש השני והשלישי. התגובה האישית משתנה."},{"category_slug":"skin-quality","service_slug":"prp","display_order":8,"title":"כמה זמן עשויה להימשך התוצאה?","answer":"לפי תיאור השירות, התוצאה עשויה להישמר עד כשנה; משך התוצאה בפועל משתנה."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":1,"title":"מה כוללת מזותרפיה?","answer":"מדובר בהזרקות שטחיות של חומרים פעילים להזנת העור ולשיפור צבעו וזוהרו. הרכב החומרים מותאם אישית לפי תיאור השירות."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הטיפול עשוי להתאים למי שהעור שלה חיוור, יבש או עייף, למשל לאחר הקיץ או תקופת לחץ. ההתאמה נקבעת בייעוץ."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":3,"title":"כמה מפגשים נדרשים?","answer":"לרוב מומלצת סדרה של ארבעה עד שישה מפגשים, בהפרש של כשבועיים עד שלושה שבועות."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":4,"title":"מה קורה במהלך הפגישה?","answer":"לאחר ניקוי ואלחוש במשחה מתבצעות הזרקות זעירות באזור הטיפול. משך והיקף התוכנית נקבעים לפי הצורך."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":5,"title":"אילו סימנים עשויים להופיע לאחר הטיפול?","answer":"אודם קל ונקודות הזרקה עשויים להופיע ולחלוף בתוך שעות עד יממה, לפי תיאור השירות."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":6,"title":"מתי ניתן להבחין בשיפור?","answer":"לפי התיאור, השיפור עשוי להיראות לאחר המפגשים הראשונים ולהתחזק לאורך הסדרה."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":7,"title":"האם נדרשת תחזוקה?","answer":"תיאור השירות מציין שנדרשת תחזוקה תקופתית לשימור התוצאה. התדירות המתאימה נקבעת בייעוץ."},{"category_slug":"skin-quality","service_slug":"mesotherapy","display_order":8,"title":"האם אפשר לשלב עם טיפול אחר?","answer":"לפי תיאור השירות ניתן לשלב עם טיפולים אחרים באותה סדרה, אך השילוב והתזמון מחייבים התאמה אישית."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":1,"title":"מה עושה פילינג רפואי?","answer":"הפילינג מסיר באופן מבוקר שכבות חיצוניות של העור ומאיץ את התחדשותן. העומק והחומר הפעיל נבחרים לפי סוג העור והמטרה."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":2,"title":"באילו מצבים ניתן לשקול פילינג?","answer":"לפי תיאור השירות, אפשר לשקול פילינג לעור לא אחיד, כתמי פיגמנטציה, אקנה ונקבוביות, ובהתאם לעומק גם לצלקות פוסט־אקנה."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":3,"title":"האם פילינג מתאים בהריון או בזמן רואקוטן?","answer":"לפי תיאור השירות, הטיפול אינו מתאים בהריון או בזמן טיפול ברואקוטן. יש למסור בייעוץ מידע על טיפולים ותרופות."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":4,"title":"מה אם העור פגוע או כהה?","answer":"הטיפול אינו מתאים לעור פגוע, ונדרשת זהירות מיוחדת בגוון עור כהה. ההחלטה על התאמה ועוצמה נעשית לאחר בדיקה."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":5,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כחצי שעה; החומר מונח לזמן מדויק ולאחר מכן מנוטרל."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":6,"title":"האם צפויים קילוף או אדמומיות?","answer":"ייתכנו אדמומיות ובהמשך קילוף שנמשך מספר ימים, בהתאם לעומק הטיפול."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":7,"title":"איך מטפלים בעור לאחר פילינג?","answer":"לפי תיאור השירות חשוב להימנע מחשיפה לשמש ולהשתמש בקרם הגנה רחב־טווח. הנחיות נוספות ייקבעו בהתאם לפילינג שנבחר."},{"category_slug":"skin-quality","service_slug":"medical-peel","display_order":8,"title":"האם נדרש יותר ממפגש אחד?","answer":"לרוב מומלצת סדרה, והשיפור עשוי להתפתח לאורכה. מספר המפגשים נקבע לפי העומק, סוג העור והמטרה."},{"category_slug":"technology","service_slug":"morpheus8","display_order":1,"title":"מהו טיפול מורפאוס 8?","answer":"הטיפול משלב מחטים זעירות עם אנרגיית גלי רדיו, ומיועד לפי התיאור למיצוק ולשיפור מרקם העור ולטיפול בצלקות אקנה."},{"category_slug":"technology","service_slug":"morpheus8","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הוא עשוי להתאים למי שיש לה רפיון קל עד בינוני, צלקות אקנה, נקבוביות מורחבות או מרקם עור לא אחיד."},{"category_slug":"technology","service_slug":"morpheus8","display_order":3,"title":"האם הטיפול מתאים לכל גווני העור?","answer":"תיאור השירות מציין התאמה לכל גווני העור, אך עדיין נדרשת בדיקה אישית לפני החלטה."},{"category_slug":"technology","service_slug":"morpheus8","display_order":4,"title":"מתי הטיפול אינו מתאים לפי המידע באתר?","answer":"לפי תיאור השירות, הטיפול אינו מתאים בהריון, עם קוצב לב או בזיהום עורי פעיל. יש לדון במצבך הרפואי בפגישה."},{"category_slug":"technology","service_slug":"morpheus8","display_order":5,"title":"כמה מפגשים מתוכננים בדרך כלל?","answer":"לרוב מומלצת סדרה של שלושה מפגשים בהפרש של שישה עד שמונה שבועות, לפי התיאור."},{"category_slug":"technology","service_slug":"morpheus8","display_order":6,"title":"כמה זמן נמשך הטיפול?","answer":"הטיפול עצמו נמשך כחצי שעה, לאחר אלחוש מקומי במשחה למשך כשעה וחצי, לפי תיאור השירות."},{"category_slug":"technology","service_slug":"morpheus8","display_order":7,"title":"מה צפוי לאחר הטיפול?","answer":"אדמומיות ונפיחות קלה למשך יום עד שלושה ימים אפשריות; לעיתים מופיעים גם סימני רשת עדינים."},{"category_slug":"technology","service_slug":"morpheus8","display_order":8,"title":"מתי מתפתח השיפור ומה חשוב לאחריו?","answer":"השיפור מתפתח לאורך שלושה עד שישה חודשים לפי התיאור. חשוב להקפיד על הגנה מהשמש; התוצאה והמשך התחזוקה משתנים."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":1,"title":"באילו מצבים משתמשים ב־IPL?","answer":"לפי תיאור השירות, ניתן לשקול IPL לכתמי שמש ופיגמנטציה, להפחתת אדמומיות ונימים ולשיפור אחידות הגוון."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הטיפול עשוי להתאים למי שמוטרדת מכתמי שמש, נמשים, אדמומיות או רוזציאה קלה, לאחר הערכת סוג העור."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":3,"title":"האם IPL מתאים לעור כהה או שזוף?","answer":"לפי תיאור השירות, הוא פחות מתאים לגווני עור כהים ולעור שזוף טרי. האבחון כולל הערכת סוג העור."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":4,"title":"כמה מפגשים בדרך כלל נדרשים?","answer":"לרוב מומלצת סדרה של כשלושה מפגשים, לפי התיאור. מספר המפגשים המדויק תלוי בהערכה."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":5,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כחצי שעה. במהלך הטיפול משתמשים בג'ל ייעודי ובמשקפי מגן."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":6,"title":"איך מרגיש הטיפול?","answer":"תיאור השירות מציין תחושת חום באזור המטופל. התחושה האישית עשויה להשתנות."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":7,"title":"מה קורה לכתמים לאחר הטיפול?","answer":"הכתמים עשויים להתכהות לפני שהם נושרים בתוך כשבוע עד עשרה ימים. ייתכן גם אודם קל למשך שעות."},{"category_slug":"technology","service_slug":"ipl-pigmentation","display_order":8,"title":"מה חשוב לעשות סביב הטיפול?","answer":"חשוב להימנע מחשיפה לשמש לפני הטיפול ואחריו ולהשתמש בקרם הגנה רחב־טווח, לפי תיאור השירות."},{"category_slug":"technology","service_slug":"co2-laser","display_order":1,"title":"למה מיועד לייזר CO2 פרקציונלי?","answer":"לפי תיאור השירות, הוא מיועד לחידוש עור עמוק, לקמטים דקים, לצלקות אקנה, לנזקי שמש ולמרקם לא אחיד."},{"category_slug":"technology","service_slug":"co2-laser","display_order":2,"title":"למי עשוי להתאים הטיפול?","answer":"הוא עשוי להתאים למי שמחפשת שינוי משמעותי במרקם העור ומוכנה לתקופת החלמה קצרה, לאחר בדיקת התאמה."},{"category_slug":"technology","service_slug":"co2-laser","display_order":3,"title":"מתי הטיפול אינו מתאים לפי המידע באתר?","answer":"לפי תיאור השירות, הוא אינו מתאים בהריון, לאחר טיפול ברואקוטן בשנה האחרונה, בזיהום פעיל או בעור שזוף."},{"category_slug":"technology","service_slug":"co2-laser","display_order":4,"title":"כמה מפגשים עשויים להידרש?","answer":"במקרים רבים מתוארים טיפול אחד עד שניים. מספר המפגשים נקבע לפי מצב העור והעוצמה המתאימה."},{"category_slug":"technology","service_slug":"co2-laser","display_order":5,"title":"כמה זמן נמשכת הפגישה?","answer":"משך הפגישה המתואר הוא כחצי שעה, לאחר הרדמה מקומית."},{"category_slug":"technology","service_slug":"co2-laser","display_order":6,"title":"כמה זמן נמשכת ההחלמה?","answer":"אדמומיות, נפיחות ותחושת צריבה עשויות להופיע בימים הראשונים, ולאחריהן קילוף שנמשך כשבוע, לפי התיאור."},{"category_slug":"technology","service_slug":"co2-laser","display_order":7,"title":"מתי רואים את השיפור?","answer":"התוצאה נראית לאחר ההחלמה ומשתפרת לאורך שלושה עד שישה חודשים, לפי תיאור השירות."},{"category_slug":"technology","service_slug":"co2-laser","display_order":8,"title":"מה נדרש לאחר הטיפול?","answer":"תיאור השירות מדגיש הקפדה על המשחות שניתנו ועל הגנה מהשמש. ההנחיות המדויקות מותאמות לפגישה."},{"category_slug":"technology","service_slug":"microneedling","display_order":1,"title":"מה עושה מיקרונידלינג?","answer":"הטיפול יוצר בעור מיקרו־פציעות מבוקרות כחלק מתהליך שמיועד לעודד יצירת קולגן ואלסטין ולשפר מרקם."},{"category_slug":"technology","service_slug":"microneedling","display_order":2,"title":"באילו מצבים ניתן לשקול מיקרונידלינג?","answer":"לפי תיאור השירות, ניתן לשקול אותו לצלקות אקנה, נקבוביות, מרקם לא אחיד או קמטוטים עדינים."},{"category_slug":"technology","service_slug":"microneedling","display_order":3,"title":"האם הטיפול מתאים לכל גווני העור?","answer":"תיאור השירות מציין התאמה לכל גווני העור. בכל מקרה נדרשת הערכה אישית של מצב העור."},{"category_slug":"technology","service_slug":"microneedling","display_order":4,"title":"מתי הטיפול אינו מתאים?","answer":"לפי תיאור השירות, הוא אינו מתאים בזמן אקנה פעיל דלקתי או בזיהום עורי."},{"category_slug":"technology","service_slug":"microneedling","display_order":5,"title":"כמה מפגשים נהוג לתכנן?","answer":"לרוב מומלצת סדרה של שלושה עד ארבעה מפגשים בהפרש של כחודש, לפי התיאור."},{"category_slug":"technology","service_slug":"microneedling","display_order":6,"title":"מה עשוי להימרח על העור בסיום?","answer":"לפי תיאור השירות, בסיום ניתן למרוח סרום מותאם או PRP. הבחירה תלויה בתוכנית הטיפול."},{"category_slug":"technology","service_slug":"microneedling","display_order":7,"title":"מה צפוי לאחר הפגישה?","answer":"אדמומיות דמוית כוויית שמש קלה למשך יום עד יומיים אפשרית, לפי תיאור השירות."},{"category_slug":"technology","service_slug":"microneedling","display_order":8,"title":"מתי מגיע השיפור לשיאו?","answer":"השיפור מצטבר לאורך הסדרה ומגיע לשיאו כשלושה חודשים לאחר המפגש האחרון, לפי התיאור."},{"category_slug":"hyperhidrosis","service_slug":"armpits","display_order":4,"title":"האם טיפול בבתי השחי מתאים לכל מי שמזיעה?","answer":"לא בהכרח. נבחנים דפוס ההזעה, מצב העור, תרופות, מחלות רקע וטיפולים שנוסו. הזעה חדשה, מפושטת או לילית מצריכה בירור רפואי לפני החלטה על טיפול מקומי."},{"category_slug":"hyperhidrosis","service_slug":"armpits","display_order":5,"title":"האם יש חלופות לטיפול בטוקסין?","answer":"כן. בתיאור הקטגוריה מצוינות חלופות כגון תכשירים נוגדי הזעה. האפשרות המתאימה תלויה באבחון ובהעדפות שלך."},{"category_slug":"hyperhidrosis","service_slug":"armpits","display_order":6,"title":"מה קורה לפני שמחליטים על טיפול?","answer":"בייעוץ סוקרים את דפוסי ההזעה, השפעתם על השגרה, טיפולים שנוסו ומצב רפואי. מוסברים חלופות וסיכונים לפני החלטה ובהסכמה מדעת."},{"category_slug":"hyperhidrosis","service_slug":"armpits","display_order":7,"title":"האם ההקלה מתחילה מיד?","answer":"התועלת עשויה להתפתח בהדרגה, אך מידת ההקלה ומשך ההשפעה משתנים מאדם לאדם."},{"category_slug":"hyperhidrosis","service_slug":"armpits","display_order":8,"title":"אילו תופעות עשויות להופיע?","answer":"ייתכנו כאב, אודם, שטפי דם או רגישות מקומית, ולעיתים חולשה באזור סמוך. הסיכונים וההתאמה נידונים בייעוץ."},{"category_slug":"hyperhidrosis","service_slug":"face","display_order":4,"title":"האם טיפול בהזעת פנים משנה את ההבעה?","answer":"המטרה היא הפחתת הזעה ולא שינוי קמטים או הבעה, אך תיתכן השפעה על תפקוד השרירים. יש לדון בסיכון לשינוי בחיוך, באסימטריה או בצניחת גבה או עפעף."},{"category_slug":"hyperhidrosis","service_slug":"face","display_order":5,"title":"האם הטיפול מתאים לכל אזור בפנים?","answer":"לא ניתן לקבוע זאת מראש. השטח וההתאמה נקבעים בבדיקה תוך הערכת תפקוד הפנים והעיניים והדיון בסיכונים ובחלופות."},{"category_slug":"hyperhidrosis","service_slug":"face","display_order":6,"title":"האם הטיפול מפחית את כל ההזעה?","answer":"ההקלה עשויה להיות חלקית או לא אחידה וזמנית, ומשך ההשפעה משתנה."},{"category_slug":"hyperhidrosis","service_slug":"face","display_order":7,"title":"מה עושים אם מופיע שינוי בתפקוד העין?","answer":"שינוי בראייה או בתפקוד העין מצריך פנייה רפואית בהקדם, לפי המידע באתר. קושי בבליעה או בנשימה או חולשה חריגה מחייבים פנייה דחופה."},{"category_slug":"hyperhidrosis","service_slug":"face","display_order":8,"title":"האם הטיפול מחליף בירור רפואי להזעה?","answer":"לא. הזעה חדשה, מפושטת או לילית או הזעה המלווה בתסמינים נוספים דורשת בירור של הגורם לפני ששוקלים טיפול מקומי."},{"category_slug":"hyperhidrosis","service_slug":"hands","display_order":4,"title":"איך מחליטים אם טיפול מתאים לכפות הידיים?","answer":"ההחלטה כוללת הערכה של דפוס ההזעה, מצב העור, מחלות רקע, טיפולים קודמים וההשפעה האפשרית על כוח האחיזה ועל פעולות עדינות."},{"category_slug":"hyperhidrosis","service_slug":"hands","display_order":5,"title":"האם אפשר להמשיך לעבוד בידיים לאחר הטיפול?","answer":"יש לדון בעבודה ובפעולות הדורשות אחיזה או דיוק, משום שחולשה זמנית והשפעה תפקודית אפשריות."},{"category_slug":"hyperhidrosis","service_slug":"hands","display_order":6,"title":"האם ההקלה בהזעה קבועה?","answer":"לא. אם מתקבלת הקלה, היא זמנית ומשתנה בין אנשים; הטיפול עשוי להפחית הזעה אך לא בהכרח להעלים אותה."},{"category_slug":"hyperhidrosis","service_slug":"hands","display_order":7,"title":"האם תכשירים מקומיים הם אפשרות?","answer":"כן. בתיאור השירות מצוינות חלופות כגון תכשירים מקומיים ויונטופורזיס, לפי התאמה. ניתן לדון בהן בייעוץ."},{"category_slug":"hyperhidrosis","service_slug":"hands","display_order":8,"title":"האם הטיפול מתאים למי שמנגנת או מבצעת עבודה עדינה?","answer":"נדרש דיון פרטני בתפקוד היד ובחשיבות המוטוריקה העדינה, משום שחולשה זמנית או השפעה על האחיזה אפשריות."},{"category_slug":"hyperhidrosis","service_slug":"chest","display_order":4,"title":"האם אפשר לדעת מראש שההזעה בחזה היא הזעת יתר?","answer":"לא בהכרח. הזעה בחזה עשויה להיות קשורה לחום, למאמץ, לתרופות או למצב רפואי אחר, ולכן יש לברר את הגורם לפני טיפול מקומי."},{"category_slug":"hyperhidrosis","service_slug":"chest","display_order":5,"title":"האם יש מידע מבוסס על טיפול באזור החזה?","answer":"המידע הקיים בתיאור מציין שהראיות באזור זה מצומצמות יותר מאשר בבתי השחי. יש לדון באי־הוודאות, בחלופות ובסיכונים לפני החלטה."},{"category_slug":"hyperhidrosis","service_slug":"chest","display_order":6,"title":"האם הטיפול מפחית את כל ההזעה?","answer":"ההקלה עשויה להיות חלקית וזמנית ומשתנה בין אנשים; הטיפול אינו בהכרח מעלים את ההזעה."},{"category_slug":"hyperhidrosis","service_slug":"chest","display_order":7,"title":"מה כולל ייעוץ לפני טיפול?","answer":"נבחנים דפוס ההזעה, מצב רפואי ותרופות, ומוסברים מגבלות הראיות, החלופות והסיכונים. ההחלטה נעשית באופן אישי."},{"category_slug":"hyperhidrosis","service_slug":"chest","display_order":8,"title":"האם טיפול בהזעה בחזה מתאים בהריון?","answer":"המקור אינו מפרט התאמה להריון עבור אזור זה. יש למסור מידע רפואי מלא ולברר התאמה אישית לפני כל החלטה."},{"category_slug":"hyperhidrosis","service_slug":"intimate-areas","display_order":4,"title":"האם כל רטיבות באזור האינטימי נובעת מהזעה?","answer":"לא. רטיבות יכולה לנבוע מהפרשות, מזיהום או ממחלת עור. נדרשת בדיקה מתאימה, במיוחד אם יש כאב, גרד, נגעים או הפרשה."},{"category_slug":"hyperhidrosis","service_slug":"intimate-areas","display_order":5,"title":"באיזה אזור עשוי להישקל טיפול?","answer":"לפי תיאור השירות, נשקל טיפול בעור חיצוני מתאים בלבד לאחר בדיקה; אין מדובר בטיפול בריריות או באיברי המין."},{"category_slug":"hyperhidrosis","service_slug":"intimate-areas","display_order":6,"title":"האם הטיפול מבוסס היטב באזור הזה?","answer":"המידע באתר מציין שהראיות מוגבלות ושהשימוש עשוי להיות מחוץ להתוויה המאושרת. יש לדון במגבלות ובחלופות לפני הסכמה."},{"category_slug":"hyperhidrosis","service_slug":"intimate-areas","display_order":7,"title":"האם הטיפול מטפל בריח?","answer":"הטיפול אינו מיועד להעלמת ריח. אם הריח או ההפרשה הם התלונה המרכזית, נדרשת הערכה נפרדת של הגורם."},{"category_slug":"hyperhidrosis","service_slug":"intimate-areas","display_order":8,"title":"האם אפשר לעצור את הבדיקה?","answer":"כן. לפי המידע באתר, הבדיקה מתחילה בשיחה ובהסבר ונדרשת הסכמה לפניה. ניתן לבקש לעצור ולדון מראש בנוכחות מלווה."},{"category_slug":"hyperhidrosis","service_slug":"scalp","display_order":4,"title":"האם טיפול בקרקפת מתאים לכל מי שמזיעה בראש?","answer":"לא ניתן לקבוע זאת ללא בדיקה. נבחנים דפוס ההזעה, מצב הקרקפת, תרופות, מחלות רקע ומעורבות אפשרית של הפנים או העורף."},{"category_slug":"hyperhidrosis","service_slug":"scalp","display_order":5,"title":"האם טיפול בקרקפת משפיע על נשירת שיער?","answer":"מטרת הטיפול המתוארת היא הפחתה זמנית של הזעה בלבד, ולא טיפול בנשירה או עידוד צמיחת שיער. נשירה מצריכה הערכה נפרדת."},{"category_slug":"hyperhidrosis","service_slug":"scalp","display_order":6,"title":"אילו תופעות או סיכונים יש להביא בחשבון?","answer":"לצד כאב וגירוי, יש לדון באפשרות של חולשה באזור סמוך, במיוחד בקרבת המצח והעפעפיים. הסיכון נבחן לפי מיקום הטיפול."},{"category_slug":"hyperhidrosis","service_slug":"scalp","display_order":7,"title":"האם ההקלה בקרקפת קבועה?","answer":"לא. התועלת עשויה להיות חלקית וזמנית, והשטח המתאים נקבע בבדיקה."},{"category_slug":"hyperhidrosis","service_slug":"scalp","display_order":8,"title":"מתי כדאי לברר הזעה לפני טיפול מקומי?","answer":"הזעה חדשה, מפושטת או לילית מחייבת בירור רפואי. טיפול מקומי אינו תחליף לבדיקת הגורם."},{"category_slug":"hyperhidrosis","service_slug":"nape","display_order":4,"title":"האם הטיפול בעורף מיועד גם למיצוק הצוואר?","answer":"לא. מטרתו המתוארת היא הפחתה זמנית של הזעה מקומית, ולא הרמת צוואר, מיצוק עור או טיפול בכאב צוואר."},{"category_slug":"hyperhidrosis","service_slug":"nape","display_order":5,"title":"איך יודעים אם ההזעה מגיעה מהעורף או מהקרקפת?","answer":"המקור אינו תמיד ברור. בבדיקה מעריכים את פיזור ההזעה; הזעה שמקורה בקרקפת או הזעה מפושטת עשויה לדרוש בירור שונה."},{"category_slug":"hyperhidrosis","service_slug":"nape","display_order":6,"title":"האם עלולה להופיע חולשה בצוואר?","answer":"כן. חולשת שרירי צוואר היא סיכון שיש לדון בו לפני החלטה, לצד כאב, רגישות ושטפי דם."},{"category_slug":"hyperhidrosis","service_slug":"nape","display_order":7,"title":"מה אם יש לי קושי בבליעה?","answer":"בעיות בליעה או חולשה קיימת מחייבות הערכה לפני טיפול. קושי חדש בבליעה או בנשימה לאחר טיפול מחייב פנייה רפואית דחופה."},{"category_slug":"hyperhidrosis","service_slug":"nape","display_order":8,"title":"האם אפשר לצפות למשך השפעה קבוע?","answer":"לא. ההקלה, אם מתקבלת, זמנית ומשתנה; הזיעה עשויה שלא להיעלם ומשך ההשפעה אינו קבוע."}]$faq_json$::jsonb) AS x(
  category_slug text,
  service_slug text,
  display_order integer,
  title text,
  answer text
);

DO $preflight$
DECLARE
  seed_count integer;
  category_count integer;
  service_count integer;
  question_count integer;
  hyperhidrosis_count integer;
  other_question_count integer;
  mismatched_seed_count integer;
BEGIN
  SELECT count(*) INTO seed_count FROM issue17_faq_seed;
  IF seed_count <> 219 THEN
    RAISE EXCEPTION 'Issue #17 expected 219 FAQ seed rows; found %', seed_count;
  END IF;

  SELECT count(*) INTO category_count FROM public.treatment_categories;
  SELECT count(*) INTO service_count FROM public.treatment_services;
  SELECT count(*) INTO question_count FROM public.treatment_questions;
  SELECT count(*) INTO hyperhidrosis_count
  FROM public.treatment_questions q
  JOIN public.treatment_services s ON s.id = q.service_id
  JOIN public.treatment_categories c ON c.id = s.category_id
  WHERE c.slug = 'hyperhidrosis';
  SELECT count(*) INTO other_question_count
  FROM public.treatment_questions q
  JOIN public.treatment_services s ON s.id = q.service_id
  JOIN public.treatment_categories c ON c.id = s.category_id
  WHERE c.slug <> 'hyperhidrosis';

  IF category_count <> 5 OR service_count <> 30 THEN
    RAISE EXCEPTION 'Issue #17 catalog baseline mismatch: categories %, services %', category_count, service_count;
  END IF;
  IF NOT (
    (question_count = 21 AND hyperhidrosis_count = 21 AND other_question_count = 0)
    OR
    (question_count = 240 AND hyperhidrosis_count = 56 AND other_question_count = 184)
  ) THEN
    RAISE EXCEPTION 'Issue #17 FAQ baseline mismatch: total %, hyperhidrosis %, other %', question_count, hyperhidrosis_count, other_question_count;
  END IF;

  SELECT count(*) INTO mismatched_seed_count
  FROM issue17_faq_seed f
  LEFT JOIN public.treatment_categories c ON c.slug = f.category_slug
  LEFT JOIN public.treatment_services s ON s.category_id = c.id AND s.slug = f.service_slug
  WHERE s.id IS NULL OR f.display_order NOT BETWEEN 1 AND 8
    OR btrim(f.title) = '' OR btrim(f.answer) = '';
  IF mismatched_seed_count <> 0 THEN
    RAISE EXCEPTION 'Issue #17 has % seed rows with missing service or invalid content', mismatched_seed_count;
  END IF;

  SELECT count(*) INTO mismatched_seed_count
  FROM issue17_faq_seed f
  JOIN public.treatment_categories c ON c.slug = f.category_slug
  JOIN public.treatment_services s ON s.category_id = c.id AND s.slug = f.service_slug
  JOIN public.treatment_questions q ON q.service_id = s.id AND q.display_order = f.display_order
  WHERE q.title IS DISTINCT FROM f.title OR q.answer IS DISTINCT FROM f.answer;
  IF mismatched_seed_count <> 0 THEN
    RAISE EXCEPTION 'Issue #17 conflicts with % existing FAQ rows; no existing FAQ will be overwritten', mismatched_seed_count;
  END IF;
END;
$preflight$;

INSERT INTO public.treatment_questions (service_id, title, answer, display_order)
SELECT s.id, f.title, f.answer, f.display_order
FROM issue17_faq_seed f
JOIN public.treatment_categories c ON c.slug = f.category_slug
JOIN public.treatment_services s ON s.category_id = c.id AND s.slug = f.service_slug
ON CONFLICT (service_id, display_order) DO NOTHING;

DO $verify$
DECLARE
  missing_or_changed integer;
  service_count integer;
  complete_service_count integer;
  question_count integer;
BEGIN
  SELECT count(*) INTO missing_or_changed
  FROM issue17_faq_seed f
  JOIN public.treatment_categories c ON c.slug = f.category_slug
  JOIN public.treatment_services s ON s.category_id = c.id AND s.slug = f.service_slug
  LEFT JOIN public.treatment_questions q ON q.service_id = s.id AND q.display_order = f.display_order
  WHERE q.id IS NULL OR q.title IS DISTINCT FROM f.title OR q.answer IS DISTINCT FROM f.answer;
  IF missing_or_changed <> 0 THEN
    RAISE EXCEPTION 'Issue #17 FAQ verification failed for % expected rows', missing_or_changed;
  END IF;

  SELECT count(*) INTO service_count FROM public.treatment_services;
  SELECT count(*) INTO complete_service_count
  FROM (
    SELECT s.id
    FROM public.treatment_services s
    LEFT JOIN public.treatment_questions q ON q.service_id = s.id
    GROUP BY s.id
    HAVING count(q.id) = 8
      AND min(q.display_order) = 1
      AND max(q.display_order) = 8
  ) complete;
  SELECT count(*) INTO question_count FROM public.treatment_questions;
  IF service_count <> 30 OR complete_service_count <> 30 OR question_count <> 240 THEN
    RAISE EXCEPTION 'Issue #17 postcondition failed: services %, complete %, questions %', service_count, complete_service_count, question_count;
  END IF;
END;
$verify$;

COMMIT;
